from abc import ABCMeta, abstractmethod
import six
import time
from .exceptions import TimeoutError, TimeoutErrorWithData
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class InputStream(object):
    """
    Input stream of a process (stdin), where input data can be written to.
    """

    @abstractmethod
    def write(self, data):
        """
        Write data to stream.

        :param bytes data: data to be written into the input stream
        """

    @abstractmethod
    def close(self):
        """
        Close the input stream.
        """


@six.add_metaclass(ABCMeta)
class OutputStream(object):
    """
    Output stream of a process (stdout or stderr), where output data can be read from.
    """

    def read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """
        logger.debug("reading from {stream_name} with size {size!r} and timeout {timeout!r}".format(
            stream_name=self._stream_name,
            size=size,
            timeout=timeout))
        data = self._read(size, timeout)
        logger.debug("data=%r", data)
        return data

    @abstractmethod
    def _read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """

    def read_until_string(self, string, timeout=None, prefix=None):
        """
        Read data from stream until a string occurs or EOF.

        :param bytes string: string to search for
        :param float timeout: timeout in seconds
        :param bytes prefix: partly read line from previous call, which timed out

        :return: read data
        :rtype: bytes
        """
        logger.debug("reading until string {string!r} from {stream_name}".format(
            stream_name=self._stream_name,
            string=string))
        return self._read_until_string(
            string=string,
            timeout=timeout,
            prefix=prefix)

    def _read_until_string(self, string, timeout=None, prefix=None):
        """
        Read data from stream until a string occurs or EOF.

        :param bytes string: string to search for
        :param float timeout: timeout in seconds
        :param bytes prefix: partly read line from previous call, which timed out

        :return: read data
        :rtype: bytes
        """
        start_time = self._get_current_time()
        data = b"" if prefix is None else prefix[:]
        while True:
            try:
                char = self._read_char(start_time, timeout)
                data += char
                if not char or data.endswith(string):
                    logger.debug("data=%r", data)
                    return data
            except TimeoutError:
                logger.debug("timeout, data=%r", data)
                raise TimeoutErrorWithData(data=data)

    def _read_char(self, start_time, timeout):
        if timeout is None:
            return self._read(size=1, timeout=timeout)
        else:
            remaining_time = self._get_remaining_time(start_time, timeout)
            if remaining_time > 0:
                return self._read(size=1, timeout=remaining_time)
            else:
                raise TimeoutError()

    def _get_remaining_time(self, start_time, timeout):
        current_time = self._get_current_time()
        elapsed_time = current_time - start_time
        return timeout - elapsed_time

    def _get_current_time(self):
        return time.time()

    def read_line(self, timeout=None, prefix=None):
        """
        Read data from stream until line end or EOF.

        :param float timeout: timeout in seconds
        :param bytes prefix: partly read line from previous call, which timed out

        :return: read data
        :rtype: bytes
        """
        logger.debug("reading line from {stream_name}".format(
            stream_name=self._stream_name))
        return self._read_until_string(
            string=b"\n",
            timeout=timeout,
            prefix=prefix)

    def __iter__(self):
        """
        Iterate over lines.

        :return: next line
        :rtype: bytes
        """
        while True:
            line = self.read_line()
            if not line:
                return
            yield line
